    l = 0
    while (k < m and l < n):
        for i in range(l, n):
            print(spiralmatrix[k][i], end=" ")
        k += 1
        for i in range(k, m):
            print(spiralmatrix[i][n - 1], end=" ")
        n -= 1
        if (k < m):
